#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string s;
    std::cin >> s;
    std::vector<char> st;
    bool ok = true;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push_back(c);
        } else {
            if (st.empty()) {
                ok = false;
                break;
            }
            char o = st.back();
            st.pop_back();
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) {
                ok = false;
                break;
            }
        }
    }
    if (!st.empty()) ok = false;
    std::cout << (ok ? "YES" : "NO") << "\n";
    return 0;
}
